using System;
using Framework.Grid;
using UnityEngine;

namespace Framework.AI.Perception
{
    /// <summary>
    /// グリッド上における視覚認識を提供する。
    /// </summary>
    /// <typeparam name="T">グリッドのセルデータ型</typeparam>
    /// <remarks>
    /// 距離、視野角、遮蔽物の順に判定する。
    /// 認識対象の検索や更新タイミングの管理は行わない。
    /// </remarks>
    public sealed class GridVisionSensor<T>
    {
        /// <summary>
        /// 認識判定に使用するグリッド。
        /// </summary>
        private readonly GridMap<T> map;

        /// <summary>
        /// 視線を遮るセルの判定処理。
        /// </summary>
        private readonly Func<Vector2Int, bool> blocksSight;

        /// <summary>
        /// 現在の認識距離。単位はセル。
        /// </summary>
        private float range;

        /// <summary>
        /// 認識距離の二乗。
        /// </summary>
        private double squaredRange;

        /// <summary>
        /// 現在の視野角。単位は度。
        /// </summary>
        private float fieldOfView;

        /// <summary>
        /// 視野角の半分に対する余弦値。
        /// </summary>
        private double cosineHalfFieldOfView;

        /// <summary>
        /// 視野角の境界判定に使用する許容誤差。
        /// </summary>
        private const double AngleTolerance = 0.0000001d;

        /// <summary>
        /// 認識判定に使用するグリッドを取得する。
        /// </summary>
        public GridMap<T> Map => map;

        /// <summary>
        /// 現在の認識距離を取得する。単位はセル。
        /// </summary>
        public float Range => range;

        /// <summary>
        /// 現在の視野角を取得する。単位は度。
        /// </summary>
        public float FieldOfView => fieldOfView;

        /// <summary>
        /// グリッド視覚センサーを生成する。
        /// </summary>
        /// <param name="map">判定対象のグリッド</param>
        /// <param name="blocksSight">視線の遮蔽判定処理</param>
        /// <param name="range">認識距離。単位はセル</param>
        /// <param name="fieldOfView">視野角。0から360度</param>
        /// <exception cref="ArgumentNullException">
        /// グリッドまたは遮蔽判定処理がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 認識距離または視野角が不正な場合に発生する。
        /// </exception>
        public GridVisionSensor(
            GridMap<T> map,
            Func<Vector2Int, bool> blocksSight,
            float range = 5f,
            float fieldOfView = 360f)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            if (blocksSight == null)
            {
                throw new ArgumentNullException(
                    nameof(blocksSight));
            }

            this.map = map;
            this.blocksSight = blocksSight;

            Configure(range, fieldOfView);
        }

        /// <summary>
        /// 認識距離と視野角を変更する。
        /// </summary>
        /// <param name="newRange">認識距離。単位はセル</param>
        /// <param name="newFieldOfView">視野角。単位は度</param>
        /// <remarks>
        /// 不正な設定の場合は既存設定を維持する。
        /// </remarks>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 認識距離または視野角が不正な場合に発生する。
        /// </exception>
        public void Configure(
            float newRange,
            float newFieldOfView)
        {
            if (float.IsNaN(newRange) ||
                float.IsInfinity(newRange) ||
                newRange < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(newRange));
            }

            if (float.IsNaN(newFieldOfView) ||
                float.IsInfinity(newFieldOfView) ||
                newFieldOfView < 0f ||
                newFieldOfView > 360f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(newFieldOfView));
            }

            range = newRange;
            fieldOfView = newFieldOfView;

            // 距離判定用の二乗値を事前計算する。
            squaredRange = (double)range * range;

            // 視野角の判定に使用する余弦値を事前計算する。
            cosineHalfFieldOfView = Math.Cos(
                fieldOfView * Math.PI / 360d);
        }

        /// <summary>
        /// 対象が視覚認識可能か判定する。
        /// </summary>
        /// <param name="origin">観測者のグリッド座標</param>
        /// <param name="facingDirection">
        /// 観測者の向き。正規化は不要。
        /// </param>
        /// <param name="target">対象のグリッド座標</param>
        /// <returns>対象を視認できる場合はtrue</returns>
        /// <remarks>
        /// 視野角360度の場合は向きを使用しない。
        /// 同一セルの対象は視認可能とする。
        /// 視野角が360度未満で向きがゼロの場合は、
        /// 同一セル以外の対象を認識しない。
        /// </remarks>
        public bool CanSee(
            Vector2Int origin,
            Vector2Int facingDirection,
            Vector2Int target)
        {
            if (!map.IsInside(origin) ||
                !map.IsInside(target))
            {
                return false;
            }

            if (origin == target)
            {
                return true;
            }

            // 対象までの相対座標を計算する。
            double offsetX = (double)target.x - origin.x;
            double offsetY = (double)target.y - origin.y;

            double squaredDistance =
                offsetX * offsetX +
                offsetY * offsetY;

            // 距離の二乗を使用して平方根の計算を省略する。
            if (squaredDistance > squaredRange)
            {
                return false;
            }

            if (fieldOfView < 360f)
            {
                if (facingDirection == Vector2Int.zero)
                {
                    return false;
                }

                // 対象方向と観測者の向きの内積を計算する。
                double facingX = facingDirection.x;
                double facingY = facingDirection.y;

                double squaredFacingLength =
                    facingX * facingX +
                    facingY * facingY;

                double dot =
                    facingX * offsetX +
                    facingY * offsetY;

                double cosine = dot / Math.Sqrt(
                    squaredFacingLength * squaredDistance);

                // 視野角の範囲外であれば認識しない。
                if (cosine + AngleTolerance <
                    cosineHalfFieldOfView)
                {
                    return false;
                }
            }

            // 距離と視野角の条件を満たした場合のみ、
            // グリッド上の遮蔽物を検査する。
            return GridLineOfSight.HasLineOfSight(
                map,
                origin,
                target,
                blocksSight);
        }

        /// <summary>
        /// 対象の視覚認識を試みる。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="origin">観測者のグリッド座標</param>
        /// <param name="facingDirection">観測者の向き</param>
        /// <param name="target">対象のグリッド座標</param>
        /// <param name="timestamp">認識時刻。単位は秒</param>
        /// <param name="stimulus">
        /// 成功時は認識情報。失敗時は既定値。
        /// </param>
        /// <returns>対象を認識した場合はtrue</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 認識時刻が不正な場合に発生する。
        /// </exception>
        public bool TryObserve(
            Guid sourceId,
            Vector2Int origin,
            Vector2Int facingDirection,
            Vector2Int target,
            double timestamp,
            out PerceptionStimulus<Vector2Int> stimulus)
        {
            stimulus = default(
                PerceptionStimulus<Vector2Int>);

            if (double.IsNaN(timestamp) ||
                double.IsInfinity(timestamp) ||
                timestamp < 0d)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(timestamp));
            }

            if (!CanSee(origin, facingDirection, target))
            {
                return false;
            }

            // 現段階では視認できた対象の信頼度を1とする。
            stimulus = new PerceptionStimulus<Vector2Int>(
                sourceId,
                PerceptionType.Sight,
                target,
                1f,
                timestamp);

            return true;
        }
    }
}
